import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  ArrowLeft,
  Check,
  Copy,
  CreditCard,
  ExternalLink,
  Image as ImageIcon,
  Loader2,
  Palette,
  Plus,
  Sparkles,
  Trash2,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import {
  communitySubscriptionAction,
  communitySubscriptionPath,
  formatCommunitySubscriptionPrice,
  normalizeCommunityPayPageConfig,
  normalizeCommunitySubscriptionTier,
  type CommunityPayPageConfig,
  type CommunitySubscriptionTier,
} from '@/lib/communitySubscriptions';
import { appToast, destructiveAction } from '@/lib/feedback';

type CommunitySubscriptionsSettingsProps = {
  community: any;
  roles: any[];
  onSubscriptionsUpdated?: () => void;
};

type TierDraft = {
  id?: string;
  name: string;
  description: string;
  price: string;
  currency: string;
  interval: 'month' | 'year';
  trialPeriodDays: string;
  roleId: string;
  slug: string;
  featuresText: string;
  isActive: boolean;
  displayOrder: number;
  pageConfig: CommunityPayPageConfig;
};

const draftFromTier = (tier: CommunitySubscriptionTier): TierDraft => ({
  id: tier.id,
  name: tier.name,
  description: tier.description || '',
  price: String(tier.price),
  currency: tier.currency,
  interval: tier.interval,
  trialPeriodDays: String(tier.trial_period_days || 0),
  roleId: tier.role_id || '',
  slug: tier.slug,
  featuresText: tier.features.join('\n'),
  isActive: tier.is_active,
  displayOrder: tier.display_order,
  pageConfig: tier.page_config,
});

const blankDraft = (community: any): TierDraft => ({
  name: '',
  description: '',
  price: '',
  currency: 'eur',
  interval: 'month',
  trialPeriodDays: '0',
  roleId: '',
  slug: '',
  featuresText: '',
  isActive: true,
  displayOrder: 0,
  pageConfig: normalizeCommunityPayPageConfig({}, {
    communityName: community.name,
    communityDescription: community.description,
    accentColor: community.branding_config?.primary_color,
  }),
});

const PayPagePreview = ({ community, draft }: { community: any; draft: TierDraft }) => {
  const page = normalizeCommunityPayPageConfig(draft.pageConfig, {
    communityName: community.name,
    communityDescription: community.description,
    tierName: draft.name || 'Membership',
    accentColor: community.branding_config?.primary_color,
  });
  const features = draft.featuresText.split('\n').map((feature) => feature.trim()).filter(Boolean).slice(0, 6);
  const price = Number(draft.price) || 0;
  return (
    <div className="relative overflow-hidden rounded-[30px] border border-white/[0.1] bg-[#09090b] p-5 shadow-[0_28px_90px_rgba(0,0,0,0.4)] sm:p-6">
      <div className="pointer-events-none absolute -right-20 -top-20 h-64 w-64 rounded-full blur-3xl" style={{ backgroundColor: `${page.accentColor}32` }} />
      {page.coverImageUrl && (
        <div className="relative mb-5 h-32 overflow-hidden rounded-[22px] border border-white/[0.08]">
          <img src={page.coverImageUrl} alt="" className="h-full w-full object-cover opacity-65" referrerPolicy="no-referrer" />
          <div className="absolute inset-0 bg-gradient-to-t from-[#09090b] to-transparent" />
        </div>
      )}
      <div className="relative">
        <p className="text-[9px] font-black uppercase tracking-[0.22em]" style={{ color: page.accentColor }}>{page.eyebrow}</p>
        <h3 className="mt-2 text-2xl font-black tracking-tight text-white">{page.headline}</h3>
        <p className="mt-2 text-xs leading-5 text-white/42">{page.subheadline}</p>
        <div className="mt-5 flex items-end gap-1">
          <span className="text-3xl font-black text-white">{formatCommunitySubscriptionPrice(price, draft.currency)}</span>
          <span className="pb-1 text-xs font-bold text-white/32">/{draft.interval}</span>
        </div>
        <div className="mt-5 space-y-2">
          <p className="text-[9px] font-black uppercase tracking-[0.18em] text-white/28">{page.benefitsTitle}</p>
          {(features.length ? features : ['Add benefits to show what members receive.']).map((feature) => (
            <div key={feature} className="flex items-start gap-2 text-xs text-white/55">
              <span className="mt-0.5 grid h-4 w-4 shrink-0 place-items-center rounded-full" style={{ backgroundColor: `${page.accentColor}2a`, color: page.accentColor }}><Check className="h-2.5 w-2.5" /></span>
              {feature}
            </div>
          ))}
        </div>
        <button type="button" className="mt-6 w-full rounded-2xl py-3 text-xs font-black text-white shadow-lg" style={{ backgroundColor: page.accentColor }}>
          {page.ctaLabel}
        </button>
        <p className="mt-3 text-center text-[9px] leading-4 text-white/24">{page.footerNote}</p>
      </div>
    </div>
  );
};

export function CommunitySubscriptionsSettings({
  community,
  roles,
  onSubscriptionsUpdated,
}: CommunitySubscriptionsSettingsProps) {
  const [tiers, setTiers] = useState<CommunitySubscriptionTier[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [draft, setDraft] = useState<TierDraft | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const loadTiers = useCallback(async () => {
    setLoading(true);
    try {
      const { data, error } = await supabase.from('community_monetization_tiers')
        .select('id,community_id,name,description,price,currency,interval,role_id,slug,features,page_config,trial_period_days,display_order,is_active,archived_at,created_at,updated_at')
        .eq('community_id', community.id)
        .is('archived_at', null)
        .order('display_order')
        .order('created_at');
      if (error) throw error;
      setTiers((data || []).map(normalizeCommunitySubscriptionTier));
    } catch (reason) {
      console.error('Error loading community subscriptions:', reason);
      appToast('Community subscriptions could not be loaded.', 'error');
    } finally {
      setLoading(false);
    }
  }, [community.id]);

  useEffect(() => {
    void loadTiers();
  }, [loadTiers]);

  const previewDraft = useMemo(() => draft ? {
    ...draft,
    pageConfig: normalizeCommunityPayPageConfig(draft.pageConfig, {
      communityName: community.name,
      communityDescription: community.description,
      tierName: draft.name || 'Membership',
      accentColor: community.branding_config?.primary_color,
    }),
  } : null, [community, draft]);

  const updatePageConfig = (updates: Partial<CommunityPayPageConfig>) => {
    setDraft((current) => current ? { ...current, pageConfig: { ...current.pageConfig, ...updates } } : current);
  };

  const handleSave = async () => {
    if (!draft) return;
    if (!draft.name.trim() || !(Number(draft.price) > 0)) {
      appToast('Add a membership name and a price above zero.', 'error');
      return;
    }
    setSaving(true);
    try {
      const response = await communitySubscriptionAction<{ tier: unknown }>('save_plan', {
        id: draft.id,
        communityId: community.id,
        name: draft.name,
        description: draft.description,
        price: Number(draft.price),
        currency: draft.currency,
        interval: draft.interval,
        trialPeriodDays: Number(draft.trialPeriodDays) || 0,
        roleId: draft.roleId || null,
        slug: draft.slug,
        features: draft.featuresText.split('\n').map((feature) => feature.trim()).filter(Boolean),
        isActive: draft.isActive,
        displayOrder: draft.displayOrder,
        pageConfig: draft.pageConfig,
      });
      const saved = normalizeCommunitySubscriptionTier(response.tier);
      setTiers((current) => {
        const withoutSaved = current.filter((tier) => tier.id !== saved.id);
        return [...withoutSaved, saved].sort((left, right) => left.display_order - right.display_order);
      });
      setDraft(null);
      onSubscriptionsUpdated?.();
      appToast(saved.is_active ? 'Membership published with a Stripe price.' : 'Membership saved as a draft.', 'success');
    } catch (reason) {
      console.error('Error saving community subscription:', reason);
      appToast(reason instanceof Error ? reason.message : 'The membership could not be saved.', 'error');
    } finally {
      setSaving(false);
    }
  };

  const handleArchive = async (tier: CommunitySubscriptionTier) => {
    const confirmed = await destructiveAction({
      title: 'Archive this membership?',
      description: 'The payment page and sidebar link will be hidden. Existing Stripe subscriptions are not canceled.',
      confirmText: 'Archive membership',
    });
    if (!confirmed) return;
    try {
      await communitySubscriptionAction('archive_plan', { tierId: tier.id });
      setTiers((current) => current.filter((candidate) => candidate.id !== tier.id));
      if (draft?.id === tier.id) setDraft(null);
      onSubscriptionsUpdated?.();
      appToast('Membership archived. Existing subscribers remain active.', 'success');
    } catch (reason) {
      appToast(reason instanceof Error ? reason.message : 'The membership could not be archived.', 'error');
    }
  };

  const copyLink = async (tier: CommunitySubscriptionTier) => {
    const url = `${window.location.origin}${communitySubscriptionPath(community.id, tier.slug)}`;
    await navigator.clipboard.writeText(url);
    setCopiedId(tier.id);
    window.setTimeout(() => setCopiedId(null), 1800);
  };

  if (draft && previewDraft) {
    return (
      <div className="space-y-6">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-3">
            <button type="button" onClick={() => setDraft(null)} className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.09] bg-white/[0.04] text-white/55 transition hover:bg-white/[0.09] hover:text-white" aria-label="Back to memberships">
              <ArrowLeft className="h-4 w-4" />
            </button>
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-300/60">Custom pay page</p>
              <h2 className="mt-1 text-xl font-black text-white">{draft.id ? 'Edit membership' : 'Create membership'}</h2>
            </div>
          </div>
          <button type="button" onClick={handleSave} disabled={saving} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-white px-5 text-xs font-black text-black transition hover:bg-zinc-200 disabled:opacity-50">
            {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
            {saving ? 'Creating Stripe plan…' : draft.isActive ? 'Save & publish' : 'Save draft'}
          </button>
        </div>

        <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_22rem]">
          <div className="space-y-5">
            <section className="rounded-[24px] border border-white/[0.08] bg-white/[0.03] p-5">
              <h3 className="font-black text-white">Plan details</h3>
              <div className="mt-5 grid gap-4 sm:grid-cols-2">
                <label className="sm:col-span-2">
                  <span className="text-xs font-bold text-white/42">Membership name</span>
                  <input value={draft.name} onChange={(event) => setDraft({ ...draft, name: event.target.value })} placeholder="Founding members" className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none transition focus:border-violet-300/35" />
                </label>
                <label className="sm:col-span-2">
                  <span className="text-xs font-bold text-white/42">Description</span>
                  <textarea value={draft.description} onChange={(event) => setDraft({ ...draft, description: event.target.value })} placeholder="Describe the paid membership and who it is for." className="mt-2 min-h-24 w-full resize-none rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none transition focus:border-violet-300/35" />
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Price</span>
                  <input type="number" min="0.5" step="0.01" value={draft.price} onChange={(event) => setDraft({ ...draft, price: event.target.value })} placeholder="19.00" className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none transition focus:border-violet-300/35" />
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Currency</span>
                  <select value={draft.currency} onChange={(event) => setDraft({ ...draft, currency: event.target.value })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-[#111113] px-4 py-3 text-sm text-white outline-none">
                    <option value="eur">EUR</option><option value="usd">USD</option><option value="gbp">GBP</option>
                  </select>
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Billing interval</span>
                  <select value={draft.interval} onChange={(event) => setDraft({ ...draft, interval: event.target.value as 'month' | 'year' })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-[#111113] px-4 py-3 text-sm text-white outline-none">
                    <option value="month">Monthly</option><option value="year">Yearly</option>
                  </select>
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Free trial days</span>
                  <input type="number" min="0" max="365" value={draft.trialPeriodDays} onChange={(event) => setDraft({ ...draft, trialPeriodDays: event.target.value })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Role after payment</span>
                  <select value={draft.roleId} onChange={(event) => setDraft({ ...draft, roleId: event.target.value })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-[#111113] px-4 py-3 text-sm text-white outline-none">
                    <option value="">Basic member access</option>
                    {roles.map((role) => <option key={role.id} value={role.id}>{role.name}</option>)}
                  </select>
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Payment-page slug</span>
                  <input value={draft.slug} onChange={(event) => setDraft({ ...draft, slug: event.target.value })} placeholder="founders" className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                </label>
                <label className="sm:col-span-2">
                  <span className="text-xs font-bold text-white/42">Benefits · one per line</span>
                  <textarea value={draft.featuresText} onChange={(event) => setDraft({ ...draft, featuresText: event.target.value })} placeholder={'Private member channels\nMonthly owner call\nResource library'} className="mt-2 min-h-28 w-full resize-none rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                </label>
                <label className="flex items-center justify-between gap-4 rounded-2xl border border-white/[0.08] bg-black/15 p-4 sm:col-span-2">
                  <span><span className="block text-sm font-black text-white">Publish in sidebar</span><span className="mt-1 block text-xs text-white/32">Drafts stay owner-only and cannot be purchased.</span></span>
                  <input type="checkbox" checked={draft.isActive} onChange={(event) => setDraft({ ...draft, isActive: event.target.checked })} className="h-5 w-5 rounded" />
                </label>
              </div>
            </section>

            <section className="rounded-[24px] border border-white/[0.08] bg-white/[0.03] p-5">
              <div className="flex items-center gap-2"><Palette className="h-4 w-4 text-violet-300" /><h3 className="font-black text-white">Pay-page content</h3></div>
              <div className="mt-5 grid gap-4 sm:grid-cols-2">
                {([
                  ['eyebrow', 'Eyebrow'], ['headline', 'Headline'], ['benefitsTitle', 'Benefits heading'], ['ctaLabel', 'Button label'],
                ] as const).map(([field, label]) => (
                  <label key={field}>
                    <span className="text-xs font-bold text-white/42">{label}</span>
                    <input value={draft.pageConfig[field]} onChange={(event) => updatePageConfig({ [field]: event.target.value })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                  </label>
                ))}
                <label className="sm:col-span-2">
                  <span className="text-xs font-bold text-white/42">Subheadline</span>
                  <textarea value={draft.pageConfig.subheadline} onChange={(event) => updatePageConfig({ subheadline: event.target.value })} className="mt-2 min-h-20 w-full resize-none rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                </label>
                <label className="sm:col-span-2">
                  <span className="text-xs font-bold text-white/42">Footer note</span>
                  <input value={draft.pageConfig.footerNote} onChange={(event) => updatePageConfig({ footerNote: event.target.value })} className="mt-2 w-full rounded-2xl border border-white/[0.09] bg-black/20 px-4 py-3 text-sm text-white outline-none" />
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Accent color</span>
                  <div className="mt-2 flex gap-2"><input type="color" value={draft.pageConfig.accentColor} onChange={(event) => updatePageConfig({ accentColor: event.target.value })} className="h-11 w-14 rounded-xl border-0 bg-transparent" /><input value={draft.pageConfig.accentColor} onChange={(event) => updatePageConfig({ accentColor: event.target.value })} className="min-w-0 flex-1 rounded-2xl border border-white/[0.09] bg-black/20 px-4 text-sm text-white outline-none" /></div>
                </label>
                <label>
                  <span className="text-xs font-bold text-white/42">Cover image URL</span>
                  <div className="relative mt-2"><ImageIcon className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/25" /><input value={draft.pageConfig.coverImageUrl} onChange={(event) => updatePageConfig({ coverImageUrl: event.target.value })} placeholder="https://…" className="w-full rounded-2xl border border-white/[0.09] bg-black/20 py-3 pl-11 pr-4 text-sm text-white outline-none" /></div>
                </label>
              </div>
            </section>
          </div>

          <aside className="xl:sticky xl:top-0 xl:self-start">
            <p className="mb-3 px-1 text-[10px] font-black uppercase tracking-[0.18em] text-white/28">Live preview</p>
            <PayPagePreview community={community} draft={previewDraft} />
          </aside>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-300/60">Stripe memberships</p>
          <h2 className="mt-1 text-2xl font-black tracking-tight text-white">Community subscriptions</h2>
          <p className="mt-1 text-sm text-white/38">Create recurring access with a custom payment page. Published plans appear in the community sidebar.</p>
        </div>
        <button type="button" onClick={() => setDraft(blankDraft(community))} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-full bg-white px-5 text-xs font-black text-black transition hover:bg-zinc-200">
          <Plus className="h-4 w-4" /> New subscription
        </button>
      </div>

      {loading ? (
        <div className="grid min-h-52 place-items-center rounded-[26px] border border-white/[0.08] bg-white/[0.025]"><Loader2 className="h-7 w-7 animate-spin text-white/45" /></div>
      ) : tiers.length === 0 ? (
        <div className="rounded-[28px] border border-dashed border-white/[0.1] bg-white/[0.025] px-6 py-14 text-center">
          <div className="mx-auto grid h-14 w-14 place-items-center rounded-full border border-violet-300/15 bg-violet-500/10 text-violet-200"><CreditCard className="h-5 w-5" /></div>
          <h3 className="mt-5 text-lg font-black text-white">No community subscriptions yet</h3>
          <p className="mx-auto mt-2 max-w-md text-sm leading-6 text-white/35">Create a real Stripe-backed plan, customize its payment page and publish it to the sidebar.</p>
          <button type="button" onClick={() => setDraft(blankDraft(community))} className="mt-6 rounded-full bg-white px-5 py-2.5 text-xs font-black text-black">Create the first plan</button>
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2">
          {tiers.map((tier) => {
            const path = communitySubscriptionPath(community.id, tier.slug);
            return (
              <article key={tier.id} className="rounded-[24px] border border-white/[0.08] bg-white/[0.035] p-5 transition hover:border-white/[0.15]">
                <div className="flex items-start justify-between gap-4">
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <h3 className="truncate text-lg font-black text-white">{tier.name}</h3>
                      <span className={`rounded-full px-2 py-1 text-[9px] font-black uppercase tracking-wider ${tier.is_active ? 'bg-emerald-400/10 text-emerald-300' : 'bg-white/[0.06] text-white/35'}`}>{tier.is_active ? 'Published' : 'Draft'}</span>
                    </div>
                    <p className="mt-1 line-clamp-2 text-xs leading-5 text-white/35">{tier.description || 'No description added.'}</p>
                  </div>
                  <div className="shrink-0 text-right">
                    <p className="font-black text-white">{formatCommunitySubscriptionPrice(tier.price, tier.currency)}</p>
                    <p className="mt-0.5 text-[10px] font-bold text-white/28">per {tier.interval}</p>
                  </div>
                </div>
                <div className="mt-5 flex flex-wrap items-center gap-2 border-t border-white/[0.06] pt-4">
                  <button type="button" onClick={() => setDraft(draftFromTier(tier))} className="flex-1 rounded-full border border-white/[0.08] bg-white/[0.05] px-4 py-2.5 text-xs font-black text-white/65 transition hover:bg-white/[0.1] hover:text-white">Edit page</button>
                  {tier.is_active && <button type="button" onClick={() => void copyLink(tier)} className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.08] bg-white/[0.04] text-white/45 transition hover:text-white" aria-label="Copy payment-page link">{copiedId === tier.id ? <Check className="h-4 w-4 text-emerald-300" /> : <Copy className="h-4 w-4" />}</button>}
                  {tier.is_active && <a href={path} target="_blank" rel="noopener noreferrer" className="grid h-10 w-10 place-items-center rounded-full border border-white/[0.08] bg-white/[0.04] text-white/45 transition hover:text-white" aria-label="Open payment page"><ExternalLink className="h-4 w-4" /></a>}
                  <button type="button" onClick={() => void handleArchive(tier)} className="grid h-10 w-10 place-items-center rounded-full border border-rose-400/10 bg-rose-500/[0.06] text-rose-300/65 transition hover:bg-rose-500/[0.12] hover:text-rose-200" aria-label="Archive membership"><Trash2 className="h-4 w-4" /></button>
                </div>
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}
