const createBlockId = () => `block-${crypto.randomUUID()}`;

export const normalizeWheelCooldownHours = (value: unknown) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.max(0, Math.min(720, parsed)) : 24;
};

export const getWheelCooldownRemainingMs = (lastSpinAt: string | null | undefined, cooldownHours: unknown, now = Date.now()) => {
  if (!lastSpinAt) return 0;
  const lastSpin = new Date(lastSpinAt).getTime();
  if (!Number.isFinite(lastSpin)) return 0;
  return Math.max(0, lastSpin + normalizeWheelCooldownHours(cooldownHours) * 60 * 60 * 1000 - now);
};

export const getCommunityAppDefinition = (appType: string) =>
  BUILT_IN_COMMUNITY_APPS.find((definition) => definition.type === appType) || CUSTOM_APP_DEFINITION;

export const createCommunityAppConfig = (appType: string) => {
  const definition = getCommunityAppDefinition(appType);
  return JSON.parse(JSON.stringify(definition.defaultConfig)) as Record<string, any>;
};

export function CommunityAppIcon({ app, className = 'h-5 w-5' }: { app: CommunityAppInstance; className?: string }) {
  const definition = getCommunityAppDefinition(app.app_type);
  const Icon = definition.icon;
  const configuredIcon = typeof app.config?.iconUrl === 'string' && /^https:\/\//i.test(app.config.iconUrl) ? app.config.iconUrl : null;
  if (app.icon_url || configuredIcon) {
    return <img src={app.icon_url || configuredIcon || ''} alt="" className={`${className} rounded-md object-cover`} loading="lazy" />;
  }
  return <Icon className={`${className} ${definition.iconClass}`} aria-hidden="true" />;
}

