  if (appType==='events') return <><div className="grid gap-4 sm:grid-cols-2"><Field label="Event title"><input value={String(config.eventTitle||'')} onChange={(event)=>update('eventTitle',event.target.value)} maxLength={120} className={inputClass}/></Field><Field label="Starts at"><input type="datetime-local" value={String(config.startsAt||inOneHour()).slice(0,16)} onChange={(event)=>update('startsAt',event.target.value)} className={inputClass}/></Field><Field label="Location"><input value={String(config.location||'')} onChange={(event)=>update('location',event.target.value)} maxLength={120} className={inputClass}/></Field><Field label="Time label"><input value={String(config.timezoneLabel||'')} onChange={(event)=>update('timezoneLabel',event.target.value)} maxLength={60} placeholder="Your local time" className={inputClass}/></Field><Field label="Capacity" hint="0 means unlimited"><input type="number" min="0" max="100000" value={Number(config.capacity||0)} onChange={(event)=>update('capacity',Math.max(0,Number(event.target.value)))} className={inputClass}/></Field><Field label="Event or livestream URL"><input type="url" value={String(config.eventUrl||'')} onChange={(event)=>update('eventUrl',event.target.value)} placeholder="https://" className={inputClass}/></Field></div><Field label="Event details"><textarea value={String(config.details||'')} onChange={(event)=>update('details',event.target.value)} maxLength={1500} className={textareaClass}/></Field><Toggle label="RSVPs are open" checked={Boolean(config.rsvpOpen)} onChange={(checked)=>update('rsvpOpen',checked)}/></>;
  if (appType==='challenges') return <><Field label="Challenge prompt"><textarea value={String(config.prompt||'')} onChange={(event)=>update('prompt',event.target.value)} maxLength={700} className={textareaClass}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Deadline"><input type="datetime-local" value={String(config.deadline||inSevenDays()).slice(0,16)} onChange={(event)=>update('deadline',event.target.value)} className={inputClass}/></Field><Field label="Maximum response length"><input type="number" min="100" max="5000" value={Number(config.responseMaxLength||1000)} onChange={(event)=>update('responseMaxLength',Math.max(100,Math.min(5000,Number(event.target.value))))} className={inputClass}/></Field></div><Toggle label="Submissions are open" checked={Boolean(config.submissionsOpen)} onChange={(checked)=>update('submissionsOpen',checked)}/><Toggle label="Show total submission count" checked={Boolean(config.showSubmissionCount)} onChange={(checked)=>update('showSubmissionCount',checked)}/></>;
  if (appType==='suggestion_box') return <><Field label="Suggestion prompt"><textarea value={String(config.prompt||'')} onChange={(event)=>update('prompt',event.target.value)} maxLength={500} className={textareaClass}/></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Ideas per member" hint="0 means unlimited"><input type="number" min="0" max="100" value={Number(config.maxIdeasPerMember||0)} onChange={(event)=>update('maxIdeasPerMember',Math.max(0,Number(event.target.value)))} className={inputClass}/></Field><Field label="Maximum idea length"><input type="number" min="80" max="2000" value={Number(config.ideaMaxLength||500)} onChange={(event)=>update('ideaMaxLength',Math.max(80,Math.min(2000,Number(event.target.value))))} className={inputClass}/></Field></div><Toggle label="New suggestions are open" checked={Boolean(config.submissionsOpen)} onChange={(checked)=>update('submissionsOpen',checked)}/><Toggle label="Voting is open" checked={Boolean(config.votingOpen)} onChange={(checked)=>update('votingOpen',checked)}/></>;
