  if (appType==='bingo') return <><div className="grid gap-4 sm:grid-cols-2"><Field label="Board label"><input value={String(config.boardLabel||'')} onChange={(event)=>update('boardLabel',event.target.value)} maxLength={80} className={inputClass}/></Field><Field label="Columns"><select value={Number(config.columns||3)} onChange={(event)=>update('columns',Number(event.target.value))} className={selectClass}>{[2,3,4,5].map((columns)=><option key={columns} value={columns}>{columns} columns</option>)}</select></Field></div><Field label="Bingo squares" hint="One square per line · maximum 25"><textarea value={asStringArray(config.items).join('\n')} onChange={(event)=>update('items',event.target.value.split('\n').map((value)=>value.trim()).filter(Boolean).slice(0,25))} className={`${textareaClass} min-h-52`}/></Field><Toggle label="Members can reset their board" checked={Boolean(config.allowReset)} onChange={(checked)=>update('allowReset',checked)}/></>;
  if (appType==='leaderboard') return <><div className="grid gap-4 sm:grid-cols-2"><Field label="Metric name"><input value={String(config.metricLabel||'')} onChange={(event)=>update('metricLabel',event.target.value)} maxLength={80} className={inputClass}/></Field><Field label="Short unit"><input value={String(config.unit||'pts')} onChange={(event)=>update('unit',event.target.value.slice(0,12))} className={inputClass}/></Field><Field label="Maximum score"><input type="number" min="1" value={Number(config.maxScore||10000)} onChange={(event)=>update('maxScore',Math.max(1,Number(event.target.value)))} className={inputClass}/></Field><Field label="Score step"><input type="number" min="1" value={Number(config.scoreStep||1)} onChange={(event)=>update('scoreStep',Math.max(1,Number(event.target.value)))} className={inputClass}/></Field><Field label="Ranking direction"><select value={String(config.sortDirection||'desc')} onChange={(event)=>update('sortDirection',event.target.value)} className={selectClass}><option value="desc">Highest score first</option><option value="asc">Lowest score first</option></select></Field></div><Toggle label="Members can report their own score" checked={Boolean(config.allowSelfReport)} onChange={(checked)=>update('allowSelfReport',checked)}/></>;
  if (appType==='check_in') return <><Field label="Daily prompt"><textarea value={String(config.prompt||'')} onChange={(event)=>update('prompt',event.target.value)} maxLength={500} className={textareaClass}/></Field><Field label="Success message"><input value={String(config.successMessage||'')} onChange={(event)=>update('successMessage',event.target.value)} maxLength={60} className={inputClass}/></Field><Toggle label="Show today’s community count" checked={Boolean(config.showCommunityCount)} onChange={(checked)=>update('showCommunityCount',checked)}/></>;
