  if (appType==='custom') return <CustomAppBuilderFields config={config} setConfig={setConfig}/>;
  if (definition.runtime !== 'special' && definition.settings?.length) return <SchemaSettingsFields fields={definition.settings} config={config} update={update} />;
  return null;
