function SchemaSettingsFields({ fields, config, update }: { fields: NonNullable<CommunityAppDefinition['settings']>; config: Record<string, any>; update: (key: string, value: any) => void }) {
  return <div className="space-y-4">{fields.map((field) => {
    const value = config[field.key];
    if (field.type === 'toggle') return <Toggle key={field.key} label={field.label} description={field.hint} checked={Boolean(value)} onChange={(checked) => update(field.key, checked)} />;
    if (field.type === 'textarea') return <Field key={field.key} label={field.label} hint={field.hint}><textarea value={String(value ?? '')} onChange={(event) => update(field.key, event.target.value)} maxLength={field.maxLength} placeholder={field.placeholder} className={textareaClass} /></Field>;
    if (field.type === 'number') return <Field key={field.key} label={field.label} hint={field.hint}><input type="number" value={Number(value ?? 0)} min={field.min} max={field.max} step={field.step} onChange={(event) => { const parsed = Number(event.target.value); update(field.key, Number.isFinite(parsed) ? Math.max(field.min ?? -Infinity, Math.min(field.max ?? Infinity, parsed)) : 0); }} className={inputClass} /></Field>;
    if (field.type === 'select') return <Field key={field.key} label={field.label} hint={field.hint}><select value={String(value ?? '')} onChange={(event) => { const selected = field.options?.find((option) => String(option.value) === event.target.value); update(field.key, selected?.value ?? event.target.value); }} className={selectClass}>{field.options?.map((option) => <option key={String(option.value)} value={String(option.value)}>{option.label}</option>)}</select></Field>;
    if (field.type === 'list') return <Field key={field.key} label={field.label} hint={field.hint}><textarea value={asStringArray(value).join('\n')} onChange={(event) => update(field.key, event.target.value.split('\n').map((item) => item.trim()).filter(Boolean).slice(0, 100))} placeholder={field.placeholder} className={`${textareaClass} min-h-48`} /></Field>;
    return <Field key={field.key} label={field.label} hint={field.hint}><input value={String(value ?? '')} onChange={(event) => update(field.key, event.target.value)} maxLength={field.maxLength} placeholder={field.placeholder} className={inputClass} /></Field>;
  })}</div>;
}

function CustomAppBuilderFields({ config, setConfig }: { config: Record<string, any>; setConfig: React.Dispatch<React.SetStateAction<Record<string, any>>> }) {
  const blocks = asCustomBlocks(config.blocks);
  const setBlocks = (next: CustomAppBlock[]) => setConfig((current)=>({...current,blocks:next}));
  const updateBlock = (index:number, updates:Partial<CustomAppBlock>) => setBlocks(blocks.map((block,blockIndex)=>blockIndex===index?{...block,...updates}:block));
  const moveBlock = (index:number,direction:-1|1) => { const target=index+direction; if(target<0||target>=blocks.length)return; const next=[...blocks]; [next[index],next[target]]=[next[target],next[index]]; setBlocks(next); };
  const addBlock = (type:CustomAppBlockType) => {
    const defaults:Record<CustomAppBlockType,CustomAppBlock> = {
      hero:{id:createBlockId(),type:'hero',eyebrow:'New section',title:'Hero title',body:'Explain what members can do here.'},
      text:{id:createBlockId(),type:'text',title:'Text section',body:'Add useful context for your members.'},
      image:{id:createBlockId(),type:'image',title:'Image title',imageUrl:'',alt:'',body:''},
      button:{id:createBlockId(),type:'button',title:'Take action',body:'Send members to the next step.',label:'Open link',url:''},
      checklist:{id:createBlockId(),type:'checklist',title:'Checklist',items:['First step','Second step','Third step']},
      form:{id:createBlockId(),type:'form',title:'Share a response',body:'Responses are saved to this app.',placeholder:'Write your response…',buttonLabel:'Save response'},
      stat:{id:createBlockId(),type:'stat',value:'{{responses}}',label:'Member responses'},
      divider:{id:createBlockId(),type:'divider'},
    };
    setBlocks([...blocks,defaults[type]]);
  };

  return <div className="space-y-5"><div className="grid grid-cols-2 gap-2 rounded-[22px] border border-white/[0.08] bg-black/20 p-1.5"><button type="button" onClick={()=>setConfig((current)=>({...current,mode:'builder'}))} className={`h-10 rounded-2xl text-xs font-black transition ${config.mode!=='embed'?'bg-white text-black':'text-white/38 hover:bg-white/[0.05]'}`}>Native builder</button><button type="button" onClick={()=>setConfig((current)=>({...current,mode:'embed'}))} className={`h-10 rounded-2xl text-xs font-black transition ${config.mode==='embed'?'bg-white text-black':'text-white/38 hover:bg-white/[0.05]'}`}>External embed</button></div>{config.mode==='embed'?<div className="space-y-4"><Field label="Secure app URL" hint="The website must allow iframe embedding"><input type="url" value={String(config.url||'')} onChange={(event)=>setConfig((current)=>({...current,url:event.target.value}))} placeholder="https://" className={inputClass}/></Field><div className="rounded-2xl border border-amber-300/12 bg-amber-400/[0.05] p-4 text-xs leading-5 text-amber-100/45">External apps keep their own design and data policies. Wersee only places the HTTPS page inside the community screen.</div></div>:<><Field label="Page background"><select value={String(config.backgroundStyle||'aurora')} onChange={(event)=>setConfig((current)=>({...current,backgroundStyle:event.target.value}))} className={selectClass}><option value="aurora">Aurora dark</option><option value="minimal">Minimal dark</option><option value="light">Clean light</option></select></Field><div className="space-y-3">{blocks.map((block,index)=><div key={block.id} className="rounded-[24px] border border-white/[0.08] bg-black/20 p-4"><div className="flex items-center gap-2"><select aria-label={`Block ${index+1} type`} value={block.type} onChange={(event)=>updateBlock(index,{type:event.target.value as CustomAppBlockType})} className="h-9 min-w-0 flex-1 rounded-xl border border-white/[0.08] bg-[#19191b] px-3 text-xs font-black capitalize text-white outline-none">{['hero','text','image','button','checklist','form','stat','divider'].map((type)=><option key={type} value={type}>{type}</option>)}</select><button type="button" disabled={index===0} onClick={()=>moveBlock(index,-1)} className="grid h-9 w-9 place-items-center rounded-xl border border-white/[0.08] text-white/38 disabled:opacity-20" aria-label="Move block up"><ArrowUp className="h-3.5 w-3.5"/></button><button type="button" disabled={index===blocks.length-1} onClick={()=>moveBlock(index,1)} className="grid h-9 w-9 place-items-center rounded-xl border border-white/[0.08] text-white/38 disabled:opacity-20" aria-label="Move block down"><ArrowDown className="h-3.5 w-3.5"/></button><button type="button" onClick={()=>setBlocks(blocks.filter((_,blockIndex)=>blockIndex!==index))} className="grid h-9 w-9 place-items-center rounded-xl border border-rose-300/10 text-rose-200/45 hover:bg-rose-400/10" aria-label="Remove block"><Trash2 className="h-3.5 w-3.5"/></button></div><div className="mt-4 grid gap-3">{block.type==='hero'?<><Field label="Eyebrow"><input value={block.eyebrow||''} onChange={(event)=>updateBlock(index,{eyebrow:event.target.value})} className={inputClass}/></Field><Field label="Title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Body"><textarea value={block.body||''} onChange={(event)=>updateBlock(index,{body:event.target.value})} className={textareaClass}/></Field></>:block.type==='text'?<><Field label="Title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Body"><textarea value={block.body||''} onChange={(event)=>updateBlock(index,{body:event.target.value})} className={textareaClass}/></Field></>:block.type==='image'?<><Field label="HTTPS image URL"><input type="url" value={block.imageUrl||''} onChange={(event)=>updateBlock(index,{imageUrl:event.target.value})} placeholder="https://" className={inputClass}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Alt text"><input value={block.alt||''} onChange={(event)=>updateBlock(index,{alt:event.target.value})} className={inputClass}/></Field></div><Field label="Caption"><textarea value={block.body||''} onChange={(event)=>updateBlock(index,{body:event.target.value})} className={textareaClass}/></Field></>:block.type==='button'?<><Field label="Section title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Description"><textarea value={block.body||''} onChange={(event)=>updateBlock(index,{body:event.target.value})} className={textareaClass}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Button label"><input value={block.label||''} onChange={(event)=>updateBlock(index,{label:event.target.value})} className={inputClass}/></Field><Field label="HTTPS link"><input type="url" value={block.url||''} onChange={(event)=>updateBlock(index,{url:event.target.value})} placeholder="https://" className={inputClass}/></Field></div></>:block.type==='checklist'?<><Field label="Checklist title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Checklist items" hint="One item per line"><textarea value={asStringArray(block.items).join('\n')} onChange={(event)=>updateBlock(index,{items:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean).slice(0,30)})} className={textareaClass}/></Field></>:block.type==='form'?<><Field label="Form title"><input value={block.title||''} onChange={(event)=>updateBlock(index,{title:event.target.value})} className={inputClass}/></Field><Field label="Description"><textarea value={block.body||''} onChange={(event)=>updateBlock(index,{body:event.target.value})} className={textareaClass}/></Field><div className="grid gap-3 sm:grid-cols-2"><Field label="Placeholder"><input value={block.placeholder||''} onChange={(event)=>updateBlock(index,{placeholder:event.target.value})} className={inputClass}/></Field><Field label="Save button"><input value={block.buttonLabel||''} onChange={(event)=>updateBlock(index,{buttonLabel:event.target.value})} className={inputClass}/></Field></div></>:block.type==='stat'?<div className="grid gap-3 sm:grid-cols-2"><Field label="Value" hint="Use {{responses}} for a live total"><input value={block.value||''} onChange={(event)=>updateBlock(index,{value:event.target.value})} className={inputClass}/></Field><Field label="Label"><input value={block.label||''} onChange={(event)=>updateBlock(index,{label:event.target.value})} className={inputClass}/></Field></div>:<p className="py-3 text-center text-xs text-white/28">A subtle divider between sections.</p>}</div></div>)}</div><div><p className="mb-3 text-[10px] font-black uppercase tracking-[0.18em] text-white/28">Add a block</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{([['hero','Hero'],['text','Text'],['image','Image'],['button','Button'],['checklist','Checklist'],['form','Form'],['stat','Stat'],['divider','Divider']] as [CustomAppBlockType,string][]).map(([type,label])=><button key={type} type="button" onClick={()=>addBlock(type)} className="inline-flex h-10 items-center justify-center gap-2 rounded-2xl border border-white/[0.08] bg-white/[0.03] text-[10px] font-black text-white/45 hover:bg-white/[0.07] hover:text-white"><Plus className="h-3.5 w-3.5"/>{label}</button>)}</div></div></>}</div>;
}

function Toggle({ label, description, checked, onChange }: { label:string; description?:string; checked:boolean; onChange:(checked:boolean)=>void }) {
  return <button type="button" role="switch" aria-checked={checked} onClick={()=>onChange(!checked)} className="flex w-full items-center justify-between gap-4 rounded-2xl border border-white/[0.08] bg-white/[0.03] px-4 py-3 text-left transition hover:bg-white/[0.055]"><span><span className="block text-xs font-bold text-white/62">{label}</span>{description?<span className="mt-1 block text-[10px] leading-4 text-white/28">{description}</span>:null}</span><span className={`relative h-6 w-11 shrink-0 rounded-full transition ${checked?'bg-emerald-400':'bg-white/10'}`}><span className={`absolute top-1 h-4 w-4 rounded-full bg-white transition ${checked?'left-6':'left-1'}`}/></span></button>;
}
