export const defineCommunityApp = (input: CommunityAppDefinitionInput): CommunityAppDefinition => ({
  ...input,
  ...PALETTES[input.palette],
  defaultConfig: {
    ...RUNTIME_DEFAULTS[input.runtime],
    description: input.description,
    ...(input.defaultConfig || {}),
  },
  settings: [...RUNTIME_SETTINGS[input.runtime], ...(input.settings || [])],
});

export const inOneHour = () => new Date(Date.now() + 60 * 60 * 1000).toISOString().slice(0, 16);
export const inSevenDays = () => new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 16);

