import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Activity,
  BarChart3,
  CreditCard,
  Loader2,
  MessageCircle,
  RefreshCw,
  TrendingDown,
  TrendingUp,
  Users,
} from 'lucide-react';
import { supabase } from '@/lib/supabase';
import {
  communitySubscriptionAction,
  formatCommunitySubscriptionPrice,
  metricChange,
  normalizeCommunityAnalytics,
  type CommunityAnalytics,
} from '@/lib/communitySubscriptions';
import { appToast } from '@/lib/feedback';

type CommunityOwnerAnalyticsProps = {
  communityId: string;
};

const changeTone = (value: number) => value >= 0 ? 'text-emerald-300' : 'text-rose-300';

const ChangeLabel = ({ current, previous }: { current: number; previous: number }) => {
  const change = metricChange(current, previous);
  const Icon = change >= 0 ? TrendingUp : TrendingDown;
  return (
    <span className={`mt-2 inline-flex items-center gap-1 text-[11px] font-bold ${changeTone(change)}`}>
      <Icon className="h-3 w-3" />
      {Math.abs(change)}% vs previous 30d
    </span>
  );
};

const AnalyticsCard = ({
  label,
  value,
  detail,
  icon: Icon,
}: {
  label: string;
  value: React.ReactNode;
  detail: React.ReactNode;
  icon: React.ComponentType<{ className?: string }>;
}) => (
  <article className="rounded-[22px] border border-white/[0.08] bg-white/[0.035] p-5 shadow-[0_16px_45px_rgba(0,0,0,0.18)]">
    <div className="flex items-start justify-between gap-3">
      <div>
        <p className="text-[10px] font-black uppercase tracking-[0.18em] text-white/32">{label}</p>
        <div className="mt-2 text-2xl font-black tracking-tight text-white">{value}</div>
      </div>
      <div className="grid h-10 w-10 place-items-center rounded-2xl border border-white/[0.08] bg-white/[0.045] text-white/55">
        <Icon className="h-4.5 w-4.5" />
      </div>
    </div>
    <div className="min-h-5">{detail}</div>
  </article>
);

export function CommunityOwnerAnalytics({ communityId }: CommunityOwnerAnalyticsProps) {
  const [analytics, setAnalytics] = useState<CommunityAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshingBilling, setRefreshingBilling] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadAnalytics = useCallback(async () => {
    setError(null);
    try {
      const { data, error: analyticsError } = await supabase.rpc('get_community_owner_analytics', {
        p_community_id: communityId,
      });
      if (analyticsError) throw analyticsError;
      setAnalytics(normalizeCommunityAnalytics(data));
    } catch (reason) {
      console.error('Error loading community owner analytics:', reason);
      setError(reason instanceof Error ? reason.message : 'Analytics could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, [communityId]);

  useEffect(() => {
    setLoading(true);
    void loadAnalytics();
  }, [loadAnalytics]);

  const handleRefreshBilling = async () => {
    setRefreshingBilling(true);
    try {
      const result = await communitySubscriptionAction<{ synced: number; failed: number }>('sync_owner', {
        communityId,
      });
      await loadAnalytics();
      appToast(
        result.failed > 0
          ? `Refreshed ${result.synced} subscriptions; ${result.failed} could not be refreshed.`
          : `Refreshed ${result.synced} subscription${result.synced === 1 ? '' : 's'} from Stripe.`,
        result.failed > 0 ? 'info' : 'success',
      );
    } catch (reason) {
      appToast(reason instanceof Error ? reason.message : 'Stripe subscription data could not be refreshed.', 'error');
    } finally {
      setRefreshingBilling(false);
    }
  };

  const maxMessages = useMemo(
    () => Math.max(1, ...(analytics?.trend.map((point) => point.messages) || [1])),
    [analytics?.trend],
  );

  if (loading) {
    return (
      <div className="grid min-h-80 place-items-center rounded-[28px] border border-white/[0.08] bg-white/[0.025]">
        <div className="text-center">
          <Loader2 className="mx-auto h-7 w-7 animate-spin text-white/55" />
          <p className="mt-3 text-sm text-white/38">Loading persisted community analytics…</p>
        </div>
      </div>
    );
  }

  if (error || !analytics) {
    return (
      <div className="rounded-[28px] border border-rose-400/15 bg-rose-500/[0.06] p-6">
        <h2 className="font-black text-white">Analytics unavailable</h2>
        <p className="mt-2 text-sm text-white/45">{error || 'No analytics response was returned.'}</p>
        <button type="button" onClick={() => void loadAnalytics()} className="mt-5 rounded-full bg-white px-4 py-2 text-xs font-black text-black">
          Try again
        </button>
      </div>
    );
  }

  const runRateLabel = analytics.monthlyRunRateByCurrency.length > 0
    ? analytics.monthlyRunRateByCurrency
      .map((rate) => formatCommunitySubscriptionPrice(rate.amount, rate.currency))
      .join(' + ')
    : formatCommunitySubscriptionPrice(0, 'eur');

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-violet-300/60">Owner view</p>
          <h2 className="mt-1 text-2xl font-black tracking-tight text-white">Community analytics</h2>
          <p className="mt-1 text-sm text-white/38">Real membership, conversation and recurring checkout records.</p>
        </div>
        <button
          type="button"
          onClick={handleRefreshBilling}
          disabled={refreshingBilling}
          className="inline-flex min-h-10 items-center justify-center gap-2 rounded-full border border-white/[0.1] bg-white/[0.05] px-4 text-xs font-black text-white/65 transition hover:bg-white/[0.1] hover:text-white disabled:opacity-50"
        >
          {refreshingBilling ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />}
          Refresh Stripe
        </button>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <AnalyticsCard
          label="Members"
          value={analytics.totalMembers.toLocaleString()}
          detail={<ChangeLabel current={analytics.newMembers30d} previous={analytics.previousNewMembers30d} />}
          icon={Users}
        />
        <AnalyticsCard
          label="30-day active"
          value={analytics.activeUsers30d.toLocaleString()}
          detail={<p className="mt-2 text-[11px] font-bold text-white/35">{analytics.engagementRate}% of members sent a message</p>}
          icon={Activity}
        />
        <AnalyticsCard
          label="Messages (30d)"
          value={analytics.messages30d.toLocaleString()}
          detail={<ChangeLabel current={analytics.messages30d} previous={analytics.previousMessages30d} />}
          icon={MessageCircle}
        />
        <AnalyticsCard
          label="Monthly run rate"
          value={runRateLabel}
          detail={<p className="mt-2 text-[11px] font-bold text-white/35">{analytics.activeSubscriptions} active or trialing</p>}
          icon={CreditCard}
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-[minmax(0,1.5fr)_minmax(18rem,0.7fr)]">
        <section className="rounded-[26px] border border-white/[0.08] bg-white/[0.03] p-5 sm:p-6">
          <div className="flex items-center justify-between gap-3">
            <div>
              <h3 className="font-black text-white">Six-month activity</h3>
              <p className="mt-1 text-xs text-white/32">Saved messages, joins and subscription starts by month.</p>
            </div>
            <BarChart3 className="h-5 w-5 text-violet-300/55" />
          </div>
          <div className="mt-7 flex h-52 items-end gap-2 sm:gap-3" aria-label="Six-month community activity chart">
            {analytics.trend.map((point) => (
              <div key={point.month} className="flex h-full min-w-0 flex-1 flex-col justify-end">
                <div className="mb-2 hidden text-center text-[9px] font-bold text-white/28 sm:block">{point.messages}</div>
                <div className="relative flex min-h-2 flex-1 items-end overflow-hidden rounded-[12px] bg-white/[0.035]">
                  <div
                    className="w-full rounded-[12px] bg-gradient-to-t from-violet-600/70 to-fuchsia-300/85 transition-[height] duration-500"
                    style={{ height: `${Math.max(4, (point.messages / maxMessages) * 100)}%` }}
                    title={`${point.messages} messages in ${point.month}`}
                  />
                </div>
                <p className="mt-2 truncate text-center text-[9px] font-black uppercase text-white/30">{point.month.slice(5)}</p>
                <p className="mt-1 truncate text-center text-[9px] text-white/22">+{point.members} · {point.subscriptions} paid</p>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-[26px] border border-white/[0.08] bg-white/[0.03] p-5 sm:p-6">
          <h3 className="font-black text-white">Most active channels</h3>
          <p className="mt-1 text-xs text-white/32">Message volume during the last 30 days.</p>
          <div className="mt-5 space-y-2">
            {analytics.topChannels.length > 0 ? analytics.topChannels.map((channel, index) => (
              <div key={channel.id || `${channel.name}-${index}`} className="flex items-center gap-3 rounded-2xl border border-white/[0.06] bg-black/15 px-3 py-3">
                <span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-white/[0.05] text-[10px] font-black text-white/35">{index + 1}</span>
                <span className="min-w-0 flex-1 truncate text-xs font-bold text-white/65">{channel.name}</span>
                <span className="text-xs font-black text-white">{channel.messages30d.toLocaleString()}</span>
              </div>
            )) : (
              <div className="rounded-2xl border border-dashed border-white/[0.08] px-4 py-8 text-center text-xs text-white/30">
                No messages were sent in the last 30 days.
              </div>
            )}
          </div>
        </section>
      </div>

      <section className="grid gap-3 sm:grid-cols-3">
        <div className="rounded-2xl border border-white/[0.07] bg-black/15 p-4">
          <p className="text-xs font-bold text-white/35">New subscriptions (30d)</p>
          <p className="mt-2 text-xl font-black text-white">{analytics.newSubscriptions30d}</p>
        </div>
        <div className="rounded-2xl border border-white/[0.07] bg-black/15 p-4">
          <p className="text-xs font-bold text-white/35">Canceled (30d)</p>
          <p className="mt-2 text-xl font-black text-white">{analytics.canceledSubscriptions30d}</p>
        </div>
        <div className="rounded-2xl border border-white/[0.07] bg-black/15 p-4">
          <p className="text-xs font-bold text-white/35">Lifetime messages</p>
          <p className="mt-2 text-xl font-black text-white">{analytics.totalMessages.toLocaleString()}</p>
        </div>
      </section>

      <p className="text-[11px] leading-5 text-white/25">
        Monthly run rate is normalized from current active and trialing plans; it is not a payout or settled-revenue figure. Currency totals are kept separate.
      </p>
    </div>
  );
}
